  1	/**
  2	 * Integration tests for the 4 knowledge MCP tools:
  3	 *   ledger_add_insight, ledger_search_insights, ledger_list_insights, ledger_update_insight
  4	 *
  5	 * Tests drive the tool handler functions directly via _internal, using vi.mock to redirect
  6	 * resolveLedgerRoot() to a temporary directory so the real ledger storage is never touched.
  7	 */
  8	import { vi, describe, it, expect, beforeEach, afterEach } from 'vitest';
  9	import { mkdtemp, rm } from 'fs/promises';
 10	import { join } from 'path';
 11	import { tmpdir } from 'os';
 12	
 13	// ─── Module-level variable updated by beforeEach ──────────────────────────
 14	let tempLedgerRoot: string;
 15	
 16	vi.mock('../../src/utils/ledger-root.js', () => ({
 17	  resolveLedgerRoot: () => tempLedgerRoot,
 18	  WORKSPACE_ROOT: '/fake/workspace',
 19	  ORCHESTRATOR_LOGS_DIR: '/fake/workspace/orchestrator/logs',
 20	  projectSlugFromPath: (p: string) => (p.split('/').pop() ?? 'unknown'),
 21	  inferProjectRootFromPlanPath: (p: string) => p,
 22	}));
 23	
 24	import { _internal } from '../../src/tools/knowledge.js';
 25	
 26	const { addInsight, searchInsights, listInsights, updateInsight } = _internal;
 27	
 28	// ─── Helpers ──────────────────────────────────────────────────────────────
 29	
 30	function parseResult(result: { content: { type: string; text: string }[] }) {
 31	  return JSON.parse(result.content[0]!.text);
 32	}
 33	
 34	function isError(result: { isError?: boolean }) {
 35	  return result.isError === true;
 36	}
 37	
 38	// ─── Setup / Teardown ─────────────────────────────────────────────────────
 39	
 40	beforeEach(async () => {
 41	  tempLedgerRoot = await mkdtemp(join(tmpdir(), 'knowledge-test-'));
 42	});
 43	
 44	afterEach(async () => {
 45	  await rm(tempLedgerRoot, { recursive: true, force: true });
 46	});
 47	
 48	// ─── ledger_add_insight ───────────────────────────────────────────────────
 49	
 50	describe('ledger_add_insight', () => {
 51	  it('creates a global insight and returns the insight with formatted_id', async () => {
 52	    const result = await addInsight({
 53	      scope: 'global',
 54	      title: 'Always use atomic writes',
 55	      content: 'Write to a temp file then rename to prevent partial writes.',
 56	      category: 'architecture',
 57	      tags: ['storage', 'reliability'],
 58	      source: 'WP-001',
 59	      confidence: 0.95,
 60	    });
 61	
 62	    const data = parseResult(result as any);
 63	    expect(data.id).toBe(1);
 64	    expect(data.formatted_id).toBe('KN-0001');
 65	    expect(data.scope).toBe('global');
 66	    expect(data.title).toBe('Always use atomic writes');
 67	    expect(data.category).toBe('architecture');
 68	    expect(data.tags).toEqual(['storage', 'reliability']);
 69	    expect(data.created_at).toBeDefined();
 70	    expect(data.repository_name).toBeUndefined();
 71	  });
 72	
 73	  it('creates a repository-scoped insight when scope is "repository" and repository_name is provided', async () => {
 74	    const result = await addInsight({
 75	      scope: 'repository',
 76	      repository_name: 'my-repo',
 77	      title: 'Repository-specific insight',
 78	      content: 'This applies only to my-repo.',
 79	      category: 'workflow',
 80	      tags: ['repository'],
 81	    });
 82	
 83	    const data = parseResult(result as any);
 84	    expect(data.scope).toBe('repository');
 85	    expect(data.repository_name).toBe('my-repo');
 86	    expect(data.formatted_id).toBe('KN-0001');
 87	  });
 88	
 89	  it('defaults source to empty string and confidence to 1 when omitted', async () => {
 90	    const result = await addInsight({
 91	      scope: 'global',
 92	      title: 'Minimal insight',
 93	      content: 'No source or confidence provided.',
 94	      category: 'testing',
 95	      tags: [],
 96	    });
 97	
 98	    const data = parseResult(result as any);
 99	    expect(data.source).toBe('');
100	    expect(data.confidence).toBe(1);

101	  });
102	
103	  it('assigns incrementing IDs to successive global insights', async () => {
104	    const r1 = await addInsight({
105	      scope: 'global',
106	      title: 'First',
107	      content: 'Content 1',
108	      category: 'c',
109	      tags: [],
110	    });
111	    const r2 = await addInsight({
112	      scope: 'global',
113	      title: 'Second',
114	      content: 'Content 2',
115	      category: 'c',
116	      tags: [],
117	    });
118	
119	    expect(parseResult(r1 as any).id).toBe(1);
120	    expect(parseResult(r2 as any).id).toBe(2);
121	  });
122	
123	  it('returns an error when scope is "repository" but repository_name is missing', async () => {
124	    const result = await addInsight({
125	      scope: 'repository',
126	      title: 'No repo name',
127	      content: 'Should fail.',
128	      category: 'c',
129	      tags: [],
130	    });
131	
132	    expect(isError(result as any)).toBe(true);
133	    expect((result as any).content[0].text).toContain('repository_name');
134	  });
135	
136	  // AC-1: scope:'repository' + repository_name + origin_plan succeeds and returns all fields
137	  it('creates a repository-scoped insight with origin_plan and returns all fields (AC-1)', async () => {
138	    const result = await addInsight({
139	      scope: 'repository',
140	      repository_name: 'hcp-editor',
141	      origin_plan: 'my-plan',
142	      title: 'HCP-editor insight',
143	      content: 'This applies only to hcp-editor.',
144	      category: 'architecture',
145	      tags: ['hcp', 'editor'],
146	      source: 'WP-004',
147	      confidence: 0.9,
148	    });
149	
150	    expect(isError(result as any)).toBe(false);
151	    const data = parseResult(result as any);
152	    expect(data.scope).toBe('repository');
153	    expect(data.repository_name).toBe('hcp-editor');
154	    expect(data.origin_plan).toBe('my-plan');
155	    expect(data.title).toBe('HCP-editor insight');
156	    expect(data.content).toBe('This applies only to hcp-editor.');
157	    expect(data.category).toBe('architecture');
158	    expect(data.tags).toEqual(['hcp', 'editor']);
159	    expect(data.source).toBe('WP-004');
160	    expect(data.confidence).toBe(0.9);
161	    expect(data.id).toBeDefined();
162	    expect(data.formatted_id).toMatch(/^KN-\d{4}$/);
163	    expect(data.created_at).toBeDefined();
164	  });
165	
166	  // AC-2: scope:'project' is rejected at the schema validation level
167	  it('rejects scope:"project" at the schema validation level (AC-2)', async () => {
168	    // The Zod schema enforces InsightScope = ['global', 'repository'].
169	    // Passing scope:'project' must fail before reaching storage.
170	    const result = await addInsight({
171	      scope: 'project' as any,
172	      title: 'Should be rejected',
173	      content: 'scope:project is no longer a valid scope value.',
174	      category: 'c',
175	      tags: [],
176	    });
177	
178	    expect(isError(result as any)).toBe(true);
179	    // The error must come from schema validation (Zod), not from storage.
180	    const errorText: string = (result as any).content[0].text;
181	    expect(errorText).toBeTruthy();
182	    // Confirm it did not create anything (global store should be empty)
183	    const list = parseResult((await listInsights({})) as any);
184	    expect(list).toHaveLength(0);
185	  });
186	});
187	
188	// ─── ledger_search_insights ───────────────────────────────────────────────
189	
190	describe('ledger_search_insights', () => {
191	  beforeEach(async () => {
192	    // Populate the store with a variety of insights
193	    await addInsight({
194	      scope: 'global',
195	      title: 'Atomic writes prevent corruption',
196	      content: 'Use temp-then-rename for safe file writes.',
197	      category: 'architecture',
198	      tags: ['storage', 'reliability'],
199	    });
200	    await addInsight({
201	      scope: 'global',
202	      title: 'Slug validation prevents path traversal',
203	      content: 'Reject slugs containing / or \\ at the schema boundary.',
204	      category: 'security',
205	      tags: ['security', 'validation'],
206	    });
207	    await addInsight({
208	      scope: 'repository',
209	      repository_name: 'test-repo',
210	      title: 'Repository convention: always write tests first',
211	      content: 'Test-driven development is mandatory for this repository.',
212	      category: 'workflow',
213	      tags: ['testing', 'workflow'],
214	    });
215	  });
216	
217	  it('returns matching insights for a query that appears in title', async () => {
218	    const result = await searchInsights({ query: 'atomic' });
219	    const data = parseResult(result as any);
220	    expect(data).toHaveLength(1);
221	    expect(data[0].title).toBe('Atomic writes prevent corruption');
222	  });
223	
224	  it('returns matching insights for a query that appears in content', async () => {
225	    const result = await searchInsights({ query: 'temp-then-rename' });
226	    const data = parseResult(result as any);
227	    expect(data).toHaveLength(1);
228	    expect(data[0].title).toBe('Atomic writes prevent corruption');
229	  });
230	
231	  it('returns matching insights for a query that appears in a tag', async () => {
232	    const result = await searchInsights({ query: 'reliability' });
233	    const data = parseResult(result as any);
234	    expect(data).toHaveLength(1);
235	    expect(data[0].tags).toContain('reliability');
236	  });
237	
238	  it('is case-insensitive', async () => {
239	    const result = await searchInsights({ query: 'ATOMIC' });
240	    const data = parseResult(result as any);
241	    expect(data).toHaveLength(1);
242	  });
243	
244	  it('returns empty array when no insights match', async () => {
245	    const result = await searchInsights({ query: 'nonexistent-xyz-query' });
246	    const data = parseResult(result as any);
247	    expect(data).toEqual([]);
248	  });
249	
250	  it('filters by scope: global returns only global insights', async () => {
251	    const result = await searchInsights({ query: 'validation', scope: 'global' });
252	    const data = parseResult(result as any);
253	    expect(data.every((i: { scope: string }) => i.scope === 'global')).toBe(true);
254	  });
255	
256	  it('filters by tags: returns only insights containing all specified tags', async () => {
257	    const result = await searchInsights({ query: 'validation', tags: ['security'] });
258	    const data = parseResult(result as any);
259	    expect(data.every((i: { tags: string[] }) => i.tags.includes('security'))).toBe(true);
260	  });
261	
262	  it('respects limit', async () => {
263	    // All 3 insights contain the letter 'e' in title
264	    const result = await searchInsights({ query: 'e', limit: 2 });
265	    const data = parseResult(result as any);
266	    expect(data.length).toBeLessThanOrEqual(2);
267	  });
268	
269	  it('includes formatted_id in results', async () => {
270	    const result = await searchInsights({ query: 'atomic' });
271	    const data = parseResult(result as any);
272	    expect(data[0].formatted_id).toMatch(/^KN-\d{4}$/);
273	  });
274	
275	  // AC-3: repository_name filter restricts search to that store only
276	  it('restricts search to a specific repository store when repository_name is provided (AC-3)', async () => {
277	    // 'test-repo' exists (from beforeEach); 'other-repo' does not
278	    // Searching for 'convention' only appears in the test-repo insight
279	    const result = await searchInsights({ query: 'convention', repository_name: 'test-repo' });
280	    const data = parseResult(result as any);
281	    expect(data.length).toBeGreaterThanOrEqual(1);
282	    expect(data.every((i: { repository_name: string }) => i.repository_name === 'test-repo')).toBe(true);
283	  });
284	
285	  it('returns empty array when repository_name filter targets a store with no matching insights (AC-3)', async () => {
286	    // 'atomic' only appears in global store; filtering to 'test-repo' must return nothing
287	    const result = await searchInsights({ query: 'atomic', repository_name: 'test-repo' });
288	    const data = parseResult(result as any);
289	    expect(data).toHaveLength(0);
290	  });
291	});
292	
293	// ─── ledger_list_insights ─────────────────────────────────────────────────
294	
295	describe('ledger_list_insights', () => {
296	  beforeEach(async () => {
297	    // Add 5 global insights in the same category
298	    for (let i = 1; i <= 5; i++) {
299	      await addInsight({
300	        scope: 'global',
301	        title: `Insight ${i}`,
302	        content: `Content ${i}`,
303	        category: 'testing',
304	        tags: i % 2 === 0 ? ['even'] : ['odd'],
305	      });
306	    }
307	    // Add 1 repository-scoped insight
308	    await addInsight({
309	      scope: 'repository',
310	      repository_name: 'repo-a',
311	      title: 'Repository insight',
312	      content: 'Repository-specific content.',
313	      category: 'workflow',
314	      tags: ['repository'],
315	    });
316	  });
317	
318	  it('returns all insights when called with no filters', async () => {
319	    const result = await listInsights({});
320	    const data = parseResult(result as any);
321	    expect(data).toHaveLength(6);
322	  });
323	
324	  it('filters by scope: global returns only global insights', async () => {
325	    const result = await listInsights({ scope: 'global' });
326	    const data = parseResult(result as any);
327	    expect(data).toHaveLength(5);
328	    expect(data.every((i: { scope: string }) => i.scope === 'global')).toBe(true);
329	  });
330	
331	  it('filters by category', async () => {
332	    const result = await listInsights({ category: 'workflow' });
333	    const data = parseResult(result as any);
334	    expect(data).toHaveLength(1);
335	    expect(data[0].category).toBe('workflow');
336	  });
337	
338	  it('filters by tags', async () => {
339	    const result = await listInsights({ tags: ['even'] });
340	    const data = parseResult(result as any);
341	    expect(data.every((i: { tags: string[] }) => i.tags.includes('even'))).toBe(true);
342	    expect(data).toHaveLength(2); // insights 2 and 4
343	  });
344	
345	  it('applies limit to restrict results', async () => {
346	    const result = await listInsights({ scope: 'global', limit: 3 });
347	    const data = parseResult(result as any);
348	    expect(data).toHaveLength(3);
349	  });
350	
351	  it('applies offset to skip results', async () => {
352	    const all = parseResult((await listInsights({ scope: 'global' })) as any);
353	    const paged = parseResult((await listInsights({ scope: 'global', offset: 2, limit: 2 })) as any);
354	    expect(paged).toHaveLength(2);
355	    expect(paged[0].id).toBe(all[2].id);
356	    expect(paged[1].id).toBe(all[3].id);
357	  });
358	
359	  it('returns empty array when offset exceeds total', async () => {
360	    const result = await listInsights({ scope: 'global', offset: 100 });
361	    const data = parseResult(result as any);
362	    expect(data).toEqual([]);
363	  });
364	
365	  it('includes formatted_id in results', async () => {
366	    const result = await listInsights({ scope: 'global', limit: 1 });
367	    const data = parseResult(result as any);
368	    expect(data[0].formatted_id).toMatch(/^KN-\d{4}$/);
369	  });
370	
371	  // AC-4: scope:'repository' + repository_name filters correctly
372	  it('filters by scope:"repository" and repository_name to return only that store\'s insights (AC-4)', async () => {
373	    const result = await listInsights({ scope: 'repository', repository_name: 'repo-a' });
374	    const data = parseResult(result as any);
375	    expect(data).toHaveLength(1);
376	    expect(data[0].scope).toBe('repository');
377	    expect(data[0].repository_name).toBe('repo-a');
378	  });
379	
